export function preferKnownHostnames(hosts) {
    const knownHosts = hosts.filter(host => host !== 'unknown');
    return knownHosts.length > 0
        ? [...knownHosts, ...hosts.filter(host => host === 'unknown')]
        : hosts;
}
export function knownHostnames(hosts) {
    return hosts.filter(host => Boolean(host) && host !== 'unknown');
}
// Hosts to offer in device pickers: everything except the "unknown" pseudo-host
// (e.g. the stopwatch bucket), unless no real host exists.
export function deviceHostnames(hosts) {
    const known = knownHostnames(hosts);
    return known.length > 0 ? known : hosts;
}
export function selectSoleKnownHostname(hosts) {
    const known = knownHostnames(hosts);
    return known.length === 1 ? known[0] : undefined;
}
export function categoryBuilderHostnameEmptyKind(hosts, hostname) {
    if (hostname) {
        return null;
    }
    return hosts.filter(Boolean).length === 0 ? 'no-hosts' : 'hostname-unselected';
}
